<x-auditor.layout :title="$order->number . ' - Audytor IT'">
    <div class="page-head"><div class="stack"><a class="button secondary" href="{{ route('delivery.audit-orders.index') }}" style="width:max-content;color:var(--text);border-color:var(--line);">Wroc</a><h1>{{ $order->number }}</h1><strong>{{ $order->title }}</strong><div class="muted">{{ $order->client->name }}{{ $order->location ? ' / '.$order->location->name : '' }} / {{ $order->auditType->name }} v{{ $order->versionDefinition->version }}</div><div class="meta"><span class="pill {{ $order->status->color() }}">{{ $order->status->label() }}</span><span class="pill">{{ $order->planned_hours }} / {{ $order->expected_hours }} h</span><span class="pill">Min. kompetencje: {{ $order->minimum_competency_level?->label() ?? '-' }}</span></div></div></div>
